-- Allow authorized condominium managers to request unit deletion.\n-- The database trigger remains the final integrity guard.\nDROP POLICY IF EXISTS "Authorized condominium managers can delete units" ON public.condominium_units;\nCREATE POLICY "Authorized condominium managers can delete units"\nON public.condominium_units\nFOR DELETE\nTO authenticated\nUSING (\n  (SELECT private.can_manage_workspace_module(condominium_units.workspace_id, 'condomini'::text))\n);\n